export function assembly(layout,parts){const found=CHARACTERS.find(g=>g.layout===layout&&g.parts.length===parts.length&&g.parts.every((p,i)=>p===parts[i]));if(found)return found;const v=ASSEMBLY_VARIANTS.find(g=>g.layout===layout&&g.parts.every((p,i)=>p===parts[i]));return v?CHARACTER_INDEX.get(v.char):null;}

