// Supplemental recipes are deliberately conservative. Keep complex independent
// forms intact until a reviewed decomposition is available.
const whole=new Set(['原','亮','春','布','步']);
const appended=[];
for(let[char,pinyin,meaning,layout,parts]of supplemental){if(CHARACTER_INDEX.has(char))continue;if(whole.has(char)){layout='single';parts=char;}const g=Object.freeze({char,pinyin,meaning,layout,parts:Object.freeze(parts.split(' '))});CHARACTER_INDEX.set(char,g);appended.push(g);}
export const ALL_CHARACTERS=Object.freeze([...CHARACTERS,...appended]);
export const ALL_PARTS=Object.freeze({...PARTS,...Object.fromEntries(appended.flatMap(g=>g.parts).filter(p=>!PARTS[p]).map(part=>[part,{part,name:part+'字部件',note:'按现代字形放置；部件不一定是部首。',radical:['纟','阝','禾'].includes(part)}]))});
export function matchCreation(layout,parts){return assembly(layout,parts)||appended.find(g=>g.layout===layout&&g.parts.length===parts.length&&g.parts.every((p,i)=>p===parts[i]))||null;}
export const CREATIONS=Object.freeze([...objectRows.map(([text,kind,category,meaning])=>({text,kind,category,meaning,isWord:false})),...words.map(([text,kind,category,meaning])=>({text,kind,category,meaning,isWord:true}))].map(x=>Object.freeze(x)));
